Cypher query: MATCH (a:Article)-[:PUBLISHED_BY]->(pub)
MATCH (a)-[:MENTIONS]->(sam:Person)
WHERE (toLower(sam.name) CONTAINS 'sam altman' OR any(alias IN coalesce(sam.aliases, []) WHERE toLower(alias) CONTAINS 'sam altman'))
  AND (
    toLower(pub.name) CONTAINS 'fortune'
    OR any(alias IN coalesce(pub.aliases, []) WHERE toLower(alias) CONTAINS 'fortune')
    OR toLower(pub.name) CONTAINS 'techcrunch'
    OR any(alias IN coalesce(pub.aliases, []) WHERE toLower(alias) CONTAINS 'techcrunch')
  )
OPTIONAL MATCH (a)-[:MENTIONS]->(mentioned)
OPTIONAL MATCH (a)-[:MENTIONS]->(openai:Organization)-[:ACCUSED_OF]->(accusation:Topic)
WHERE toLower(openai.name) CONTAINS 'openai'
   OR any(alias IN coalesce(openai.aliases, []) WHERE toLower(alias) CONTAINS 'openai')
RETURN DISTINCT a.name AS article, a.published_on AS published_on, pub.name AS publisher,
       collect(DISTINCT mentioned.name) AS mentioned_entities,
       collect(DISTINCT accusation.name) AS accusation_topics
LIMIT 10
